<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { riskApi } from '../api/risk'

const alerts=ref<any[]>([]),batches=ref<any[]>([]),scheduler=ref<any>(null),batchTotal=ref(0),batchPage=ref(1),batchPageSize=ref(8),batchStatus=ref(''),selectedBatch=ref<any>(null),selectedBatchDetail=ref<any>(null),error=ref(''),message=ref(''),loading=ref(true),working=ref(''),selected=ref<any>(null)
const form=ref({status:'investigating',assessment_result:'insufficient_information',assessment_note:'',customer_consulted:false,customer_consultation_note:'',disposition_code:'REQUEST_MATERIALS',disposition_note:''})
const detailMessage=(e:any)=>{const detail=e?.response?.data?.detail;return typeof detail==='object'?(detail.message||detail.code||'风险预警处理失败'):(detail||e?.message||'风险预警处理失败')}
const actionLabels:Record<string,string>={HOLD_ORDER:'挂起订单',REJECT_ORDER:'拒绝订单',RESTRICT_TRADING:'限制交易',RELEASE_RESTRICTION:'解除交易限制',REQUEST_MATERIALS:'要求补充材料',CREATE_INVESTIGATION:'创建调查工单',CREATE_REPORT_DRAFT:'生成报告草稿',ESCALATE:'升级处理'}
const executable=new Set(['HOLD_ORDER','REJECT_ORDER','RESTRICT_TRADING','REQUEST_MATERIALS','CREATE_INVESTIGATION','CREATE_REPORT_DRAFT','ESCALATE']);const alertStatusText:Record<string,string>={open:'待接单',acknowledged:'已接单',investigating:'调查中',pending_customer:'等待客户补充',report_pending:'报告待生成',resolved:'已结案',dismissed:'已忽略'};const batchStatusText:Record<string,string>={running:'运行中',completed:'完成',completed_with_errors:'完成（有错误）',failed:'失败'};const alertLevelText:Record<string,string>={critical:'严重',high:'高',medium:'中',low:'低'};const assessmentResultText:Record<string,string>={confirmed_risk:'确认风险',cleared_after_review:'评估后通过',false_positive:'误报',insufficient_information:'信息不足'};const workOrderStatusText:Record<string,string>={open:'待处理',assigned:'已分配',in_progress:'客户已补件，待风控复核',pending_customer:'等待客户补充',resolved:'已解决',closed:'已关闭',cancelled:'已取消'};const actionStatusText:Record<string,string>={not_started:'未开始',running:'执行中',completed:'已完成',failed:'失败'}
const batchPages=computed(()=>Math.max(1,Math.ceil(batchTotal.value/batchPageSize.value)))
async function load(){loading.value=true;try{const [alertRes,batchRes,schedulerRes]=await Promise.all([riskApi.alerts(),riskApi.batches({status:batchStatus.value,limit:batchPageSize.value,offset:(batchPage.value-1)*batchPageSize.value}),riskApi.schedulerStatus()]);alerts.value=alertRes.data.data.items;batches.value=batchRes.data.data.items;scheduler.value=schedulerRes.data.data;batchTotal.value=batchRes.data.data.total}catch(e:any){error.value=detailMessage(e)}finally{loading.value=false}}
function changeBatchFilter(){batchPage.value=1;load()}
function changeBatchPage(delta:number){batchPage.value=Math.min(Math.max(1,batchPage.value+delta),batchPages.value);load()}
function openBatchDetail(batch:any){selectedBatchDetail.value=batch}
function parseBatchErrors(batch:any){try{return JSON.parse(batch.error_summary||'[]')}catch{return []}}
async function viewBatch(batch:any){working.value=batch.id;try{const res=(await riskApi.batchAlerts(batch.id,{limit:100})).data.data;alerts.value=res.items;selectedBatch.value=res.batch;message.value=`正在查看 AML 批次 ${batch.batch_key} 的关联预警` }catch(e:any){error.value=detailMessage(e)}finally{working.value=''}}
async function clearBatch(){selectedBatch.value=null;message.value='';await load()}
async function retryBatch(batch:any){working.value=batch.id;try{const res=(await riskApi.retryBatch(batch.id)).data.data;message.value=`已提交 ${res.retry_runs.length} 个失败客户的补跑；刷新批次列表查看结果。`;await load()}catch(e:any){error.value=detailMessage(e)}finally{working.value=''}}
async function lateRescan(batch:any){working.value=batch.id;try{const res=(await riskApi.lateRescan(batch.id)).data.data;message.value=res.created?'已创建迟到流水补扫批次。':'该窗口已有补扫批次，已复用。';await load()}catch(e:any){error.value=detailMessage(e)}finally{working.value=''}}
function openWorkOrder(id:string){window.location.assign(`/backoffice?section=workorders&work_order_id=${encodeURIComponent(id)}`)}
async function take(a:any){working.value=a.id;try{message.value='';await riskApi.handle(a.id,{status:'acknowledged',note:'管理员已接单'});await load()}catch(e:any){error.value=detailMessage(e)}finally{working.value=''}}
function openProcess(a:any){
  selected.value=a; error.value=''; message.value=''
  const needsMaterials=a.status==='pending_customer'
  form.value={
    status: needsMaterials ? 'pending_customer' : 'investigating',
    assessment_result: needsMaterials ? 'insufficient_information' : '',
    assessment_note: a.assessment_note || '',
    customer_consulted: Boolean(a.customer_consulted),
    customer_consultation_note: a.customer_consultation_note || '',
    disposition_code: needsMaterials ? 'REQUEST_MATERIALS' : 'NO_ACTION',
    disposition_note: a.action_note || '',
  }
}
const dispositionHelp:Record<string,string>={
  NO_ACTION:'仅保存调查进展；不会改变订单或客户交易权限。',
  REQUEST_MATERIALS:'创建客户可见的风控补件工单；客户提交材料前订单继续被拦截。',
  HOLD_ORDER:'暂停关联订单，等待进一步调查。',
  REJECT_ORDER:'拒绝关联订单；适用于确认不能继续办理的单笔业务。',
  RESTRICT_TRADING:'限制客户后续资金类业务；解除限制需到客户详情执行“解除交易限制”。',
  CREATE_INVESTIGATION:'记录并升级内部调查，不替代客户补件工单。',
  CREATE_REPORT_DRAFT:'生成报告草稿，通常配合确认风险使用。',
  ESCALATE:'升级给更高层级处理，当前预警保持调查状态。',
}
const processMode=computed(() => {
  const code=form.value.disposition_code
  if(code==='REQUEST_MATERIALS') return 'materials'
  if(['HOLD_ORDER','REJECT_ORDER','RESTRICT_TRADING','CREATE_REPORT_DRAFT','ESCALATE','CREATE_INVESTIGATION'].includes(code)) return 'risk'
  return 'review'
})
function applyDispositionDefaults(){
  if(form.value.disposition_code==='REQUEST_MATERIALS'){
    form.value.status='pending_customer'; form.value.assessment_result='insufficient_information'; form.value.customer_consulted=false
  } else if(form.value.status==='pending_customer') {
    form.value.status='investigating'
  }
}
async function submit(){
  if(!selected.value)return
  error.value=''; message.value=''
  const materialRequest=form.value.disposition_code==='REQUEST_MATERIALS'
  if(materialRequest&&(!form.value.disposition_note.trim()||!form.value.assessment_note.trim())){error.value='要求客户补充资料时，必须填写“当前信息不足的原因”和“具体资料清单”。';return}
  if(materialRequest){form.value.status='pending_customer';form.value.assessment_result='insufficient_information'}
  if(form.value.assessment_result==='cleared_after_review'&&(!form.value.customer_consulted||!form.value.customer_consultation_note.trim()||!form.value.assessment_note.trim())){error.value='评估后通过必须填写评估依据、勾选已与客户沟通并记录沟通内容。';return}
  if(form.value.status==='resolved'&&form.value.assessment_result==='confirmed_risk'){error.value='确认风险不能直接结案，请选择继续调查、限制交易、挂起/拒绝订单或生成报告草稿。';return}
  working.value=selected.value.id
  try{
    const code=form.value.disposition_code
    if(executable.has(code)){await riskApi.action(selected.value.id,{action_code:code,note:form.value.disposition_note||form.value.assessment_note})}
    await riskApi.handle(selected.value.id,form.value)
    message.value=materialRequest?'已创建客户可见的风控补件工单，并已发送站内通知；客户可在“我的工单”提交说明和附件。':'风险预警已保存。'
    selected.value=null;await load()
  }catch(e:any){error.value=detailMessage(e)}finally{working.value=''}
}
onMounted(load)
</script>
<template><section class="table-module"><div class="module-header"><div><span class="module-kicker">风险控制</span><h2>风险预警</h2><p>确认风险后必须执行真实处置；仅登记结论不会自动限制账户或订单。</p></div><span class="table-summary">{{alerts.length}} 条</span></div><p v-if="error" class="error">{{error}}</p><p v-if="message" class="success">{{message}}</p><section v-if="!loading" class="aml-batch-panel"><div class="aml-batch-head"><div><span>每日 AML 扫描</span><h3>最近 AML 扫描批次</h3></div><div class="aml-batch-tools"><select v-model="batchStatus" @change="changeBatchFilter"><option value="">全部状态</option><option value="completed">完成</option><option value="completed_with_errors">完成（有错误）</option><option value="failed">失败</option><option value="running">运行中</option></select><small>共 {{batchTotal}} 个批次</small></div></div><div v-if="batches.length" class="module-table-wrap"><table class="admin-table compact-table"><thead><tr><th>扫描窗口</th><th>状态</th><th>客户</th><th>新增预警</th><th>失败</th><th>操作</th></tr></thead><tbody><tr v-for="batch in batches" :key="batch.id"><td><strong>{{new Date(batch.scan_window_start).toLocaleDateString('zh-CN')}} ~ {{new Date(batch.scan_window_end).toLocaleDateString('zh-CN')}}</strong><small>{{batch.run_type==='late_rescan'?'迟到流水补扫':batch.run_type==='retry'?'失败客户补跑':'日批扫描'}} · {{batch.scan_days}} 天窗口</small><small v-if="batch.source_batch_id">来源批次：{{batch.source_batch_id}}</small></td><td><span class="status-badge" :class="batch.status">{{batchStatusText[batch.status]||batch.status}}</span></td><td>{{batch.succeeded_customers}} / {{batch.total_customers}}</td><td>{{batch.created_alerts}}</td><td>{{batch.failed_customers}}</td><td><button class="table-action" :disabled="working===batch.id" @click="viewBatch(batch)">查看关联预警</button><button v-if="batch.error_summary" class="table-action" @click="openBatchDetail(batch)">错误详情</button><button v-if="['failed','completed_with_errors'].includes(batch.status)" class="table-action" :disabled="working===batch.id" @click="retryBatch(batch)">补跑失败客户</button><button v-if="['completed','completed_with_errors'].includes(batch.status)" class="table-action" :disabled="working===batch.id" @click="lateRescan(batch)">补扫迟到流水</button></td></tr></tbody></table></div><div v-else class="table-empty">暂无 AML 扫描批次</div><div v-if="batchTotal>batchPageSize" class="batch-pager"><button class="table-action" :disabled="batchPage===1" @click="changeBatchPage(-1)">上一页</button><span>第 {{batchPage}} / {{batchPages}} 页</span><button class="table-action" :disabled="batchPage===batchPages" @click="changeBatchPage(1)">下一页</button></div></section><div v-if="selectedBatch" class="batch-context"><span>当前批次：{{new Date(selectedBatch.scan_window_start).toLocaleString('zh-CN')}} ~ {{new Date(selectedBatch.scan_window_end).toLocaleString('zh-CN')}}</span><button class="table-action" @click="clearBatch">返回全部预警</button></div><div v-if="loading" class="empty">正在读取风险预警…</div><div v-else class="module-table-wrap"><table class="admin-table"><thead><tr><th>客户</th><th>规则</th><th>等级</th><th>证据</th><th>评估</th><th>风险工单</th><th>实际动作</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="a in alerts" :key="a.id"><td>{{a.customer_name||'未知客户'}}</td><td>{{a.rule_code}}</td><td>{{alertLevelText[a.alert_level]||a.alert_level}}</td><td class="truncate-cell">{{a.recommendation}}；{{JSON.stringify(a.evidence)}}</td><td>{{assessmentResultText[a.assessment_result]||a.assessment_result||'待评估'}}<small>{{a.assessment_note}}</small></td><td><template v-if="a.work_order_id"><strong>{{a.work_order_ticket_no}}</strong><small>{{workOrderStatusText[a.work_order_status]||a.work_order_status}}</small><small v-if="a.latest_customer_supplement">客户补件：{{a.latest_customer_supplement}}</small><button class="table-action" @click="openWorkOrder(a.work_order_id)">查看工单</button></template><small v-else>无关联工单</small></td><td>{{a.action_code?`${actionLabels[a.action_code]||a.action_code}（${actionStatusText[a.action_status]||a.action_status||'—'}）`:'未执行'}}<small>{{a.action_note}}</small><small v-if="a.restriction_status==='restricted'" class="risk-restricted-note">当前账户已限制交易</small></td><td><span class="status-badge" :class="a.status">{{alertStatusText[a.status]||a.status}}</span></td><td><button v-if="a.status==='open'" class="table-action" :disabled="working===a.id" @click="take(a)">接单</button><button v-if="!['resolved','dismissed'].includes(a.status)" class="table-action" :disabled="working===a.id" @click="openProcess(a)">{{a.status==='acknowledged'?'评估处理':'继续处置'}}</button><small v-if="a.restriction_status==='restricted'" class="risk-restricted-note">请在客户管理详情中解除交易限制</small></td></tr><tr v-if="!alerts.length"><td colspan="9" class="table-empty">暂无风险预警</td></tr></tbody></table></div><Teleport to="body"><div v-if="selected" class="admin-modal-backdrop risk-process-backdrop" @click.self="selected=null"><div class="admin-modal risk-process-modal"><h3>风险预警处置</h3><p class="risk-action-hint">先选择本次要做的处置，界面只显示该场景真正需要填写的内容。客户补件会创建“我的工单”并发送站内通知；限制、挂起和拒绝会立即影响交易门禁。</p><label>本次处置<select v-model="form.disposition_code" @change="applyDispositionDefaults"><option value="NO_ACTION">继续调查 / 暂不执行动作</option><option value="REQUEST_MATERIALS">要求客户补充资料</option><option value="HOLD_ORDER">挂起关联订单</option><option value="REJECT_ORDER">拒绝关联订单</option><option value="RESTRICT_TRADING">限制客户交易</option><option value="CREATE_REPORT_DRAFT">生成报告草稿</option><option value="ESCALATE">升级处理</option><option value="CREATE_INVESTIGATION">创建内部调查</option></select><small>{{dispositionHelp[form.disposition_code]}}</small></label><div v-if="processMode==='materials'" class="risk-form-section"><strong>客户补件要求</strong><label>当前信息不足的原因<textarea v-model="form.assessment_note" placeholder="例如：无法确认本次资金来源和交易目的" /></label><label>请客户补充的资料清单<textarea v-model="form.disposition_note" placeholder="例如：资金来源说明、交易用途说明、相关合同或凭证" /></label><small>保存后将创建客户可见的“风控调查”工单；客户补充前，风险预警和订单拦截继续有效。</small></div><div v-else class="risk-form-section"><label>处理状态<select v-model="form.status"><option value="investigating">继续调查</option><option value="resolved">结案</option></select></label><label>评估结论<select v-model="form.assessment_result"><option value="">暂不下结论</option><option value="insufficient_information">信息不足</option><option value="cleared_after_review">评估后通过</option><option value="false_positive">误报</option><option value="confirmed_risk">确认风险</option></select></label><label>评估说明<textarea v-model="form.assessment_note" placeholder="记录规则证据、核验结果和判断依据" /></label><small v-if="form.assessment_result==='cleared_after_review' && selected?.restriction_status==='restricted'" class="risk-hint">该预警当前限制了该客户交易。保存复核结论后，请到【客户管理】详情页执行"解除交易限制"，再回到这里结案。</small><template v-if="form.assessment_result==='cleared_after_review'"><label><input type="checkbox" v-model="form.customer_consulted" /> 已与客户沟通</label><label>沟通记录<textarea v-model="form.customer_consultation_note" placeholder="沟通时间、客户说明及核验结论" /></label></template><label v-if="form.disposition_code!=='NO_ACTION'">处置说明<textarea v-model="form.disposition_note" placeholder="说明为什么执行该动作及后续安排" /></label><small v-if="form.assessment_result==='confirmed_risk'">确认风险不能直接结案；请选择继续调查、限制交易、挂起/拒绝订单或生成报告草稿。</small></div><div><button @click="selected=null">取消</button><button class="primary" :disabled="working===selected.id" @click="submit">执行处置并保存</button></div></div></div></Teleport><Teleport to="body"><div v-if="selectedBatchDetail" class="admin-modal-backdrop" @click.self="selectedBatchDetail=null"><div class="admin-modal detail-modal"><div class="modal-header"><div><span class="module-kicker">AML 批次错误</span><h3>批次错误摘要</h3></div><button class="modal-close" @click="selectedBatchDetail=null">×</button></div><dl class="detail-grid"><dt>批次键</dt><dd class="mono">{{selectedBatchDetail.batch_key}}</dd><dt>扫描窗口</dt><dd>{{new Date(selectedBatchDetail.scan_window_start).toLocaleString('zh-CN')}} ~ {{new Date(selectedBatchDetail.scan_window_end).toLocaleString('zh-CN')}}</dd><dt>状态</dt><dd>{{batchStatusText[selectedBatchDetail.status]||selectedBatchDetail.status}}</dd><dt>失败客户数</dt><dd>{{selectedBatchDetail.failed_customers}}</dd></dl><div class="batch-error-list"><div v-for="(item,index) in parseBatchErrors(selectedBatchDetail)" :key="index"><strong>{{item.username||item.user_id||'未知客户'}}</strong><p>{{item.error}}</p></div><p v-if="!parseBatchErrors(selectedBatchDetail).length">{{selectedBatchDetail.error_summary||'该批次没有结构化错误摘要。'}}</p></div></div></div></Teleport></section></template>
